scripts.bleed:
// Bleeding: at the start of the turn, try to staunch the wound (d20 + Grit against 12).
// Made it: the bleeding stops. Missed: lose 1 Vigour and keep bleeding.
if (!ctx.self) return [];
var grit = ctx.self.stats.grit || 0, die = roll(20), total = die + grit;
var sum = "(" + die + " + " + grit + " = " + total + ")";
if (total >= 12) return [
  { cond: "bleeding", on: false },
  { say: "{name} staunches the wound " + sum + "." }
];
return [
  { stat: "hp", op: "add", value: -1 },
  { say: "{name} bleeds: 1 Vigour lost " + sum + ", 12 would stop it." }
];

scripts.crit:
// A natural 20 on an attack: roll on the critical table. The last row rolls twice more.
const TABLE = [
  { upTo: 2, text: "a deep cut", bleed: true, hurt: 1 },
  { upTo: 4, text: "swept off their feet", prone: true },
  { upTo: 5, text: "a crushing blow", dice: 2 },
  { upTo: 6, text: "a flurry", again: 2 }
];
function row(n) {
  for (const r of TABLE) if (n <= r.upTo) return r;
  return TABLE[0];
}
export default function (ctx, roll) {
  if (!ctx.target) return [];
  const said = [];
  let hurt = 0, bleed = false, prone = false, todo = 1;
  for (let i = 0; i < todo && i < 5; i++) {
    const r = row(roll(6));
    said.push(r.text);
    if (r.again) { todo += r.again; continue; }
    hurt += r.hurt || 0;
    for (let d = 0; d < (r.dice || 0); d++) hurt += roll(6);
    bleed = bleed || !!r.bleed;
    prone = prone || !!r.prone;
  }
  const edits = [];
  if (hurt) edits.push({ stat: "hp", op: "add", value: -hurt, who: "target" });
  if (bleed) edits.push({ cond: "bleeding", on: true, who: "target" });
  if (prone) edits.push({ cond: "prone", on: true, who: "target" });
  edits.push({ say: "Critical on {target}: " + said.join(", ") + (hurt ? " (" + hurt + " more)." : ".") });
  return edits;
}
